export function sourceEligibleForUse(source={},use='INTERNAL_DERIVED'){if(source.rightsState!=='APPROVED')return{allowed:false,reason:'RIGHTS_NOT_APPROVED'};const modes=new Set(source.allowedUses||[]);if(!modes.has(use))return{allowed:false,reason:'USE_NOT_ALLOWED'};if(source.expiresAt&&Date.parse(source.expiresAt)<=Date.now())return{allowed:false,reason:'RIGHTS_EXPIRED'};return{allowed:true,reason:'APPROVED'};}
